function showLinkModal(links,ipName,module){var modal=document.createElement('div');modal.style.position='fixed';modal.style.zIndex='1000';modal.style.left='0';modal.style.top='0';modal.style.width='100%';modal.style.height='100%';modal.style.overflow='auto';modal.style.backgroundColor='rgba(0, 0, 0, 0.6)';modal.style.display='flex';modal.style.justifyContent='center';modal.style.alignItems='center';var modalContent=document.createElement('div');modalContent.style.backgroundColor='#ffffff';modalContent.style.padding='30px';modalContent.style.borderRadius='10px';modalContent.style.boxShadow='0 4px 8px rgba(0, 0, 0, 0.2)';modalContent.style.width='90%';modalContent.style.maxWidth='500px';modalContent.style.textAlign='center';modalContent.style.fontFamily='Arial, sans-serif';var closeButton=document.createElement('span');closeButton.innerHTML='&times;';closeButton.style.color='#333';closeButton.style.float='right';closeButton.style.fontSize='24px';closeButton.style.fontWeight='bold';closeButton.style.cursor='pointer';closeButton.onclick=function(){document.body.removeChild(modal);};var message=document.createElement('p');if(links.length===2){var word1=links[0].url.match(/hal_([a-zA-Z0-9]+)_/)[1].toUpperCase();var word2=links[1].url.match(/hal_([a-zA-Z0-9]+)_/)[1].toUpperCase();var module=module.toUpperCase();message.textContent=`The HAL1 ${module} has been split into HAL2 ${word1} and HAL2 ${word2}.`;}else{message.textContent=`Which migration do you need to know in HAL2 for ${ipName}?`;}
message.style.fontSize='18px';message.style.fontWeight='bold';message.style.marginBottom='20px';modalContent.appendChild(closeButton);modalContent.appendChild(message);links.forEach(function(link,index){var button=document.createElement('button');var word=link.url.match(/hal_([a-zA-Z0-9]+)_/)[1].toUpperCase();button.textContent=`Refer to HAL2 ${word}`;button.style.margin='10px 0';button.style.padding='10px 20px';button.style.fontSize='16px';button.style.color='#ffffff';button.style.backgroundColor='#007BFF';button.style.border='none';button.style.borderRadius='5px';button.style.cursor='pointer';button.style.width='100%';button.style.textAlign='center';button.style.transition='background-color 0.3s';button.onmouseover=function(){button.style.backgroundColor='#0056b3';};button.onmouseout=function(){button.style.backgroundColor='#007BFF';};button.onclick=function(){window.location.href=link.url;};modalContent.appendChild(button);});modal.appendChild(modalContent);document.body.appendChild(modal);}
